// Авторски кратки уроци и упражнения. Подтемите са редакционни, а не номерация на МОН.
const resourceBank={};
function addResources(grade,unit,rows){(resourceBank[grade]??=[]).push(...rows.map(r=>({unit,title:r[0],learn:r[1],task:r[2],type:r[3],prompt:r[4],items:r[5].split('~').map(s=>s.split('=>')),hint:r[6],id:resourceBank[grade].length+rows.indexOf(r)+1})));}
addResources(3,'Информация и дигитални устройства',[
['Информацията около нас','Получаваме информация чрез текст, образи, звук и други сигнали. Дигиталните устройства могат да я съхраняват и показват по различни начини. Една история може да бъде разказана с рисунка, написана с думи или записана с глас.','Нарисувай табела за класната стая. До нея напиши същото послание с едно изречение. Обясни кой вариант би разбрал човек, който още не може да чете.','match','Свържи примера с начина на представяне.','Разказ в книга=>Текст~Песен=>Звук~Снимка на котка=>Изображение~Анимация с говор=>Образ и звук','Помисли как възприемаш посланието: четеш, слушаш или гледаш.'],
['Устройства и предназначение','Клавиатурата и мишката помагат да подаваме команди. Мониторът показва резултата. Някои устройства имат повече от една роля: сензорният екран показва картина и приема докосване.','Разгледай работното си място. Назови четири устройства и покажи как ги използваш. Не разкачвай кабели.','match','Кое устройство ти е нужно?','Да напиша дума=>Клавиатура~Да посоча бутон=>Мишка~Да видя рисунка=>Монитор~Да чуя запис=>Тонколони','Разделяй въвеждането на команда от получаването на резултат.'],
['Мишка, клавиатура и въвеждане','Едно щракване избира, а двойното обикновено отваря обект. Влаченето премества при задържан бутон. Enter потвърждава или започва нов ред според приложението; Backspace изтрива знака пред курсора.','В текстов редактор напиши „Моят робот е на 3 години.“. Добави нов ред и поправи нарочно сгрешена буква.','match','Свържи действието с подходящото средство.','Изтрий знака пред курсора=>Backspace~Напиши главна буква с друг клавиш=>Shift~Вмъкни интервал=>Space~Премести избрана фигура с мишката=>Влачене','Shift се държи заедно с буквата; Space добавя празно място.'],
['Файл и папка','Файлът е запазена работа, например рисунка. Папката помага да подредим файловете. Ясното име и избраното място ни помагат да намерим работата отново. Записването и затварянето са различни действия.','С помощта на учителя създай папка „Моите рисунки“. Запази в нея собствена рисунка като „Слънце“. Затвори и я отвори отново.','order','Подреди безопасното запазване на нова рисунка.','Избирам командата за запис~Избирам папката~Въвеждам име на файла~Потвърждавам записа и проверявам файла','Не затваряй програмата, преди да запазиш работата.']]);
addResources(3,'Безопасност в дигитална среда',[
['Работно място и грижа за устройствата','Сядаме удобно, държим напитките далеч от техниката и правим почивки. При проблем с кабел или устройство викаме учител. Не се опитваме да поправяме електрическа техника сами.','Създай рисунка с три правила за кабинета. Добави знак за почивка и знак за забранени напитки.','match','Кое действие е подходящо?','Виждам повреден кабел=>Казвам на учителя~Уморени са ми очите=>Правя почивка~Имам сок=>Оставям го далеч от техниката~Програмата е блокирала=>Търся помощ','Безопасната реакция не изисква да пипаш кабели.'],
['Лични данни и помощ онлайн','Името, домашният адрес и паролата не са едно и също, но всички изискват внимателно отношение. Не даваме адрес или парола на непознат. При притеснително съдържание спираме и търсим доверен възрастен.','Измисли герой с псевдоним. Нарисувай профил без истинско име, адрес или снимка на ученик.','match','Избери подходящата реакция.','Непознат иска парола=>Не я споделям~Съобщение ме плаши=>Казвам на доверен възрастен~Искат домашния ми адрес=>Не го изпращам~Трябва ми публичен псевдоним=>Измислям име за герой','Доверието не се доказва чрез изпращане на тайни данни.']]);
addResources(3,'Последователни действия и повторения',[
['Какво е алгоритъм','Алгоритъмът описва точни стъпки за постигане на резултат. Редът има значение: обувките се обуват след чорапите. Компютърът следва зададените инструкции и не отгатва какво сме имали предвид.','Дай на съученик инструкции да нарисува къща от квадрат и триъгълник. Не показвай готова рисунка. Сравнете резултатите.','order','Подреди алгоритъм за отваряне на запазена рисунка.','Намирам папката с рисунката~Избирам файла~Отварям файла~Проверявам дали виждам нужната рисунка','Първо намираме мястото, после избираме конкретния файл.'],
['Движение по мрежа','Командите нагоре, надолу, наляво и надясно задават посока по полето. Всяка команда може да означава една клетка. Маршрутът е последователност от такива команди.','Отвори „Програмирай Роби“. Планирай маршрут, изпълни го и поправи командите, ако роботът не е при звездата.','number','Робот тръгва от долния ляв ъгъл на поле 5 × 5. Колко команди са нужни без препятствия?','До горния ляв ъгъл=>4~От горния ляв до горния десен=>4~За целия маршрут през тези два края=>8','Брой преместванията между клетките, а не броя на клетките.'],
['Повтарящи се действия','Когато една поредица се изпълнява няколко пъти, използваме повторение. „Повтори 4 пъти: стъпка и пляскане“ изпълнява и двете действия при всяко повторение.','Измисли танц с две движения и го повтори три пъти. Опиши го с една команда за повторение.','number','Пресметни действията в повторението.','Повтори 3 пъти: направи 2 стъпки. Общо стъпки?=>6~Повтори 4 пъти: плясни веднъж. Общо пляскания?=>4~Повтори 5 пъти: смени костюм. Общо смени?=>5','Умножи броя повторения по действията във всяко повторение.']]);
addResources(3,'Визуална среда за програмиране',[
['Сцена, герой и блокове','В Scratch сцената е мястото на действието, а спрайтът е герой или друг обект. Блоковете описват неговата програма. Избраният герой има собствени скриптове и костюми.','В Scratch избери фон и два героя. Посочи кой герой е избран и къде е неговият код. Запази проекта с ясно име.','match','Свържи елемента с ролята му.','Сцена=>Място на действието~Спрайт=>Програмируем обект~Блок=>Команда или управляващ елемент~Костюм=>Външен вид на спрайта','Фонът принадлежи на сцената, а костюмът — на спрайта.'],
['Събитие и начало на програма','Събитието задейства действия: зеленото знаме или натиснат клавиш могат да започнат скрипт. Блоковете под събитието се изпълняват в зададения ред.','Направи две програми: при зеленото знаме героят поздравява; при интервал се премества. Изпробвай двете начала.','match','Избери как да започне действието.','Старт на проекта=>При щракване на зеленото знаме~Действие с интервал=>Когато клавиш Space е натиснат~Действие при щракване върху героя=>Когато този спрайт е щракнат~Спиране на изпълнението=>Червен бутон Стоп','Различните събития могат да задействат различни скриптове.'],
['Костюми и анимация','Анимацията създава впечатление за движение чрез промени във времето. Смяната на костюм с кратко изчакване прави промяната видима. Движение по сцената и смяна на костюм са различни действия.','Избери герой с два костюма. Повтори шест пъти смяна на костюм и изчакване 0,3 секунди.','order','Подреди плана за кратка анимация.','Избирам герой с поне два костюма~Добавям събитие за начало~Добавям повторение със смяна на костюм и изчакване~Стартирам и проверявам анимацията','Провери костюмите, преди да програмираш тяхната смяна.']]);
addResources(3,'Текст и звук във визуална среда',[
['Говор и диалог','Блокът „кажи“ показва текстово балонче. За диалог героите трябва да се изчакват. Ако и двамата говорят едновременно, историята се следи трудно.','Направи поздрав между два героя. Първият говори 2 секунди, вторият изчаква 2 секунди и отговаря.','number','Изчисли кога започва следващата реплика при последователен разговор.','Първа реплика 2 секунди: кога започва втората?=>2~Първа 2 секунди и втора 3 секунди: общо?=>5~Три реплики по 2 секунди: общо?=>6','При последователен разговор продължителностите се събират.'],
['Запис и възпроизвеждане на звук','Звуците са част от проекта. Можем да използваме разрешен готов звук или собствен запис с разрешение. Блокът за звук до край изчаква приключването му, преди да продължи.','Добави кратък звук към герой. Изпробвай разликата между започване на звук и възпроизвеждане до край. Не записвай чужд глас без разрешение.','match','Кое действие ти е необходимо?','Да добавя звук от библиотеката=>Избор на звук~Да създам собствен звук=>Запис с микрофон~Да довърша звука преди следващ блок=>Пусни звук до край~Да променя колко силно се чува=>Настройка на сила на звука','Микрофонът въвежда звук; тонколоните го възпроизвеждат.']]);
addResources(3,'Анимиран проект',[
['Сценарий и създаване на история','Сценарият описва героите, мястото и реда на случките. Разделяме историята на малки части, програмираме ги и проверяваме резултата.','Създай история „Изгубеното семенце“ с два героя, един фон, диалог и движение. Добави начало и край.','order','Подреди работата по проекта.','Описвам историята с три изречения~Избирам герои и фон~Програмирам действията и диалога~Тествам и поправям грешките~Представям готовата история','Планът предхожда кода, а представянето идва след проверката.'],
['Откриване на грешки и представяне','Грешката е възможност да сравним очакваното и полученото. Проверяваме началото на скрипта, реда на блоковете и изчакванията. Представянето показва какво прави проектът и как сме го създали.','Нарочно размени два блока в своята история. Стартирай, опиши разликата и възстанови работещия ред.','match','Къде първо ще провериш?','Героят не започва при знамето=>Събитието за начало~Героите говорят едновременно=>Изчакванията~Героят се движи в нежелана посока=>Командата за движение~След повторен старт е на старото място=>Началната позиция','Тествай по една промяна, за да разбереш какъв е ефектът.']]);
addResources(4,'Информация и дигитални устройства',[
['Видове информация и обработка','Устройствата приемат данни, обработват ги, съхраняват ги и извеждат резултат. При снимане камерата приема образ; приложението може да го изреже; файлът пази снимката.','Опиши как създаваш и запазваш снимка на собствена рисунка. Посочи въвеждане, обработка, съхранение и извеждане.','match','Свържи примера с информационната дейност.','Снимам рисунка=>Въвеждане~Изрязвам снимката=>Обработка~Запазвам файл=>Съхранение~Показвам я на екрана=>Извеждане','Един проект използва няколко информационни дейности.'],
['Управление на устройства и файлове','Операционната система помага да управляваме приложения и файлове. Копирането създава втори екземпляр; преместването сменя мястото. Преди изтриване проверяваме избрания обект.','Създай папки „Работа“ и „Готово“. Копирай собствена рисунка, преименувай копието и премести само копието в „Готово“.','match','Кое действие е подходящо?','Искам второ копие=>Копиране~Искам друго местоположение=>Преместване~Искам по-ясно име=>Преименуване~Искам да видя съдържанието=>Отваряне','Преместването не означава да създадеш второ копие.']]);
addResources(4,'Дигитална идентичност и безопасност',[
['Профил и дигитална следа','Публикации, снимки и коментари оставят дигитална следа. Настройките за поверителност ограничават достъпа, но не гарантират, че съдържанието няма да бъде копирано. Използваме учебни профили според указанията на възрастен.','Направи хартиен профил на измислен герой. Отбележи кои данни могат да са публични и кои не трябва да се споделят.','match','Свържи ситуацията с решението.','Публикувам чужда снимка=>Първо искам съгласие~Непознат иска адрес=>Не го изпращам~Получавам обида=>Запазвам доказателство и търся помощ~Избирам публично име за игра=>Използвам псевдоним','При притеснение се обръщаме към доверен възрастен.'],
['Авторство и надеждност на информацията','Чуждите рисунки имат автор. Преди използване търсим разрешение или подходящ лиценз и посочваме източника. Публикуваното онлайн може да е грешно; сравняваме го с надежден източник.','Създай собствена картинка за проект. Ако използваш чужд материал, запиши автора, адреса и разрешението.','match','Каква проверка е нужна?','Искам чужда рисунка в играта=>Проверявам разрешението~Виждам невероятна новина=>Сравнявам с надежден източник~Използвам разрешена снимка=>Посочвам автора и източника~Не знам дали мога да използвам файл=>Търся помощ от учителя','Наличието на картинка в търсачка не е разрешение за употреба.']]);
addResources(4,'Визуална среда за програмиране',[
['Разклонен алгоритъм','Условието има стойност вярно или невярно. Блокът „ако… иначе“ избира един от два клона. Например при докосване на цел получаваме точка, а иначе продължаваме движението.','В Scratch направи герой, който при щракване проверява дали докосва друг спрайт. Нека каже „Намерих те!“ или „Търся…“.','match','Ако точките са поне 5, показваме „Победа“, иначе „Продължи“.','Точки = 2=>Продължи~Точки = 5=>Победа~Точки = 8=>Победа~Точки = 0=>Продължи','„Поне 5“ включва и точно 5.'],
['Аритметични действия и сравнения','Аритметичните блокове пресмятат числа. Блоковете за сравнение проверяват отношение и дават вярно или невярно. Знакът за равенство в условие проверява дали стойностите съвпадат.','Направи герой, който пита за две числа и показва техния сбор. После сравни числата и покажи дали са равни.','number','Пресметни стойностите на блоковете.','7 + 5=>12~9 - 4=>5~3 * 4=>12~18 / 3=>6','Провери всяко пресмятане отделно.'],
['Логически оператори','„И“ изисква и двете условия да са верни. „Или“ изисква поне едно вярно условие. „Не“ обръща стойността на условието.','Опиши правило за игра: вратата се отваря, когато героят има ключ И е до вратата. Тествай четирите комбинации от вярно и невярно.','match','За „имам ключ И съм до вратата“ избери резултат.','Ключ: да; до вратата: да=>Вярно~Ключ: да; до вратата: не=>Невярно~Ключ: не; до вратата: да=>Невярно~Ключ: не; до вратата: не=>Невярно','При „И“ само комбинацията с две верни условия е вярна.'],
['Променливи и точки','Променливата пази стойност, която може да се променя. При нова игра задаваме начални точки, а при събитие ги увеличаваме. Задаване и промяна с число са различни операции.','Създай променлива „точки“. При зеленото знаме я нулирай, а при щракване върху героя я увеличавай с 1.','number','Проследи стойността на точките.','Задай 0; промени с 1=>1~Задай 5; промени с 2=>7~Задай 3; промени с -1=>2~Задай 9; после задай 0=>0','„Задай“ заменя стойността; „промени с“ добавя към нея.'],
['Случайни числа','Случайният избор в Scratch може да върне цяло число между две зададени граници включително. Така героите могат да се появяват на различни места или да задават различни задачи.','Създай зар: при щракване показвай случайно число от 1 до 6. Изпробвай поне десет пъти и запиши резултатите.','match','Може ли да се получи от „случайно число от 1 до 6“?','1=>Да~6=>Да~0=>Не~7=>Не','И двете граници са допустими, но числата извън тях не са.'],
['Синхронизиране със съобщения','Съобщението е сигнал между скриптове. Един герой може да го изпрати, а друг да започне действие при получаване. „Разпространи и изчакай“ изчаква скриптовете, задействани от съобщението.','Направи сцена: първият герой поздравява и изпраща „Твой ред“. Вторият отговаря при получаване на това съобщение.','order','Подреди замисления разговор.','Първият герой започва при знамето~Първият герой казва поздрав до край~Първият герой изпраща „Твой ред“~Вторият реагира при получаване на „Твой ред“','Сигналът се изпраща след приключването на първата реплика.']]);
addResources(4,'Програмируеми устройства',[
['Робот, програма и сензор','Програмируемото устройство изпълнява инструкции. Сензорът отчита нещо от средата, например светлина или разстояние. Моторът създава движение. В симулация можем безопасно да проверим алгоритъм преди работа с реален робот.','В играта с Роби планирай маршрут с повторения. Обясни как сензор за препятствие би помогнал на истински робот.','match','Свържи компонента с предназначението.','Сензор за разстояние=>Открива близък обект~Мотор=>Задвижва колело~Програма=>Задава инструкции~Бутон за включване=>Пуска устройството според указанията','Сензорът измерва, а моторът изпълнява движение.'],
['Безопасно включване и изпълнение','Реалният робот се използва според указанията на учителя и производителя. Осигуряваме свободно поле, проверяваме връзката и изпълняваме кратка проба. Не поставяме пръсти до движещи части.','Създай правила за работа с учебен робот. Ако няма устройство, разиграйте алгоритъма на пода с ученик в ролята на робот.','order','Подреди учебната проба.','Получавам указания от учителя~Подготвям свободно безопасно поле~Включвам и свързвам по указанията~Изпълнявам кратка пробна програма~Спирам и изключвам по указанията','Подготовката предхожда движението.']]);
addResources(4,'Образователни игри и дигитален проект',[
['Правила на образователна игра','Играта има цел, правила, обратна връзка и край. Образователната игра упражнява конкретно умение. Първо правим малък работещ вариант, след това добавяме детайли.','Проектирайте „Събери правилния отговор“ за събиране до 20. Опишете правилен отговор, грешен отговор, точки и край на играта.','match','Свържи елемента с примера.','Учебна цел=>Упражнявам събиране~Обратна връзка=>Показвам защо отговорът е верен~Правило=>Верният отговор носи точка~Край=>След пет задачи показвам резултат','Точките сами по себе си не обясняват учебната цел.'],
['Тестване на игра','Тестът проверява дали играта следва правилата. Изпробваме правилен, грешен и граничен отговор. След нов старт точките и позициите трябва да се върнат в начално състояние.','Покани съученик да изпробва играта ти. Запиши два проблема и как ги поправи.','match','Кой тест проверява условието?','Играта дава точка при вярно=>Въвеждам верен отговор~Играта не дава точка при грешно=>Въвеждам грешен отговор~Играта започва отначало=>Стартирам повторно~Играта приключва след пет задачи=>Решавам и петата задача','Тествай и поведение, което не е успешен ход.'],
['Разработване и защита на проект','Екипът разпределя задачи и събира работата в общ продукт. При представяне обясняваме целта, показваме играта и разказваме за проверките. Посочваме използваните външни ресурси.','Създай еко игра с начало, герой, задача, точки и край. Представи я за две минути без лични данни на ученици.','order','Подреди етапите на проекта.','Избирам цел и правила~Разпределяме задачите~Създаваме работещ вариант~Тестваме и подобряваме~Представяме и посочваме източниците','Проектът е готов за представяне след тестване.']]);
addResources(5,'Компютърни системи и информационни дейности',[
['Хардуер, софтуер и информационни дейности','Хардуерът е физическата част на системата, а софтуерът са програмите. Данните се въвеждат, обработват, съхраняват и извеждат. Едно устройство може да има повече от една функция.','Създай схема на работа: запис на глас, изрязване на тишината, запазване и прослушване. Посочи устройството или програмата на всяка стъпка.','match','Разпредели примерите.','Клавиатура=>Хардуер~Браузър=>Софтуер~Монитор=>Хардуер~Текстов редактор=>Софтуер','Можеш ли физически да докоснеш обекта като част от техниката?'],
['Потребителски интерфейс и диалогови прозорци','Интерфейсът включва менюта, бутони и полета. Диалоговият прозорец иска избор. Важно е да четем съобщенията, преди да потвърдим, особено при изтриване или замяна на файл.','В Paint отвори прозореца за запис. Намери името на файла, папката, формата и бутоните за запис и отказ. Отмени без промяна.','match','За какво служи елементът?','Поле за име=>Въвеждане на текст~Бутон Отказ=>Отмяна на диалога~Меню=>Избор на команда~Лента за превъртане=>Разглеждане на скритата част','Бутонът потвърждава действие, а полето приема стойност.'],
['Носители, файлове и папки','Файловете се организират в папки. Пътят описва местоположение, а разширението подсказва формат. Промяната само на разширението не преобразува съдържанието на файла в друг формат.','Създай „Еко проект“ с папки „Текст“, „Снимки“ и „Презентация“. Запази собствена рисунка в подходящата папка. Покажи пътя до нея.','match','Свържи файла с папката.','pokаna.docx=>Текст~listo.png=>Снимки~predstavyane.pptx=>Презентация~otchet.odt=>Текст','DOCX и ODT са текстови формати, PNG е изображение.'],
['Копиране, преместване и изтриване','Копирането оставя оригинала, преместването сменя местоположението, а преименуването променя името. Проверяваме съдържанието на папката, за да видим резултата от операцията.','Копирай своя рисунка в „Готово“, преименувай копието и премести само него в друга папка. Изтрий само изрично създаден ненужен учебен файл.','match','Избери операцията според целта.','Искам файлът на две места=>Копиране~Искам файлът само в друга папка=>Преместване~Искам друго име=>Преименуване~Искам да премахна ненужен учебен файл=>Изтриване','След всяка операция провери къде остава оригиналът.']]);
addResources(5,'Интернет и електронна поща',[
['Браузър, търсачка и безопасност','Браузърът отваря уебстраници, а търсачката открива страници по ключови думи. Проверяваме адреса и източника. При съмнителни съобщения не даваме пароли и търсим помощ.','Потърси „разделно събиране хартия“. Сравни два източника по автор, дата и съвпадение на фактите.','match','Кое използваш?','Отварям известен уебадрес=>Браузър~Намирам страници по ключови думи=>Търсачка~Запазвам полезен адрес=>Отметка~Проверявам кой публикува=>Автор и източник','Първият резултат не е автоматично най-надеждният.'],
['Адрес, парола и части на писмото','Електронното писмо има получател, тема и текст; може да има приложение. Адресът съдържа локална част и домейн, разделени с @. Паролата защитава достъпа и не се пише в писмото.','В учебната пощенска работилница напиши покана до uchitel@example.com с тема, поздрав, дата, място и подпис на измислен герой.','match','Свържи частта с предназначението.','Получател=>До кого е писмото~Тема=>Кратко описание на съдържанието~Прикачен файл=>Допълнителен документ~Парола=>Тайна за достъп до акаунта','Получателят и темата не се заместват от текста на писмото.'],
['Изпращане, получаване и прикачени файлове','Преди изпращане проверяваме адреса, темата и приложенията. Получен файл от непознат може да е опасен. В учебна симулация не изпращаме реални писма.','Подготви писмо с прикрепена собствена рисунка. Провери дали името на приложения файл съвпада с описанието. Изпращай реално само по указание на учителя.','order','Подреди проверката на писмо.','Въвеждам получения от учителя учебен адрес~Добавям ясна тема и текст~Прикачвам нужния учебен файл~Проверявам адреса и приложението~Изпращам само след разрешение за реална поща','Последната проверка може да предотврати изпращане към грешен адрес.'],
['Търсене и използване на изображения','Търсим с точни ключови думи и проверяваме условията за употреба. Изображението онлайн може да има авторски права. Запазваме автора, адреса и разрешението, за да ги посочим в проекта.','Намери разрешено за използване изображение на листо или нарисувай свое. Запиши произхода му.','match','Свържи ситуацията с проверката.','Намирам изображение=>Проверявам автор и разрешение~Има дата на публикация=>Сравнявам с нужния период~Картинката е моя=>Мога да посоча собствено авторство~Не е ясно разрешението=>Избирам собствена рисунка или питам учителя','Наличието в интернет не отменя авторските права.']]);
addResources(5,'Звукова и видео информация',[
['Звук, видео и възпроизвеждане','Звукът и видеото имат продължителност. Възпроизвеждането може да се стартира, спира и превърта. Силата на звука трябва да е умерена. Записването на чужд образ или глас изисква съобразяване със съгласието.','Направи с разрешение 10-секунден аудио призив за опазване на природата. Прослушай, провери яснотата и запази с подходящо име.','match','Свържи командата с действието.','Play=>Възпроизвеждане~Pause=>Временно спиране~Volume=>Сила на звука~Timeline=>Място във времето','Pause запазва текущия момент за продължаване.']]);
addResources(5,'Компютърна графика',[
['Отваряне, рисуване и запазване','Растерното изображение е съставено от пиксели. Отварянето зарежда файл, а записването съхранява промените. Използваме ново име, ако искаме да запазим оригинала.','Нарисувай парк в Paint с четка, линия и елипса. Запази PNG файл и направи втори вариант с добавено дърво.','match','Избери инструмент.','Прав път=>Линия~Кръгло слънце=>Елипса~Свободна трева=>Четка~Оцветяване на затворена област=>Запълване','Проверявай дали контурът е затворен преди запълване.'],
['Цветова палитра и надписи','Палитрата задава цвят, а текстовият инструмент добавя надпис. Контрастът между текст и фон влияе на четимостта. Проверяваме правописа, преди да приключим редакцията.','Създай знак „Пази водата“ с до пет цвята. Добави заглавие и кратък призив върху четим фон.','match','Кое решение е подходящо?','Бял фон и бледожълт надпис=>Слаб контраст~Бял фон и тъмносин надпис=>Добър контраст~Незатворен контур и запълване=>Риск да се оцвети фонът~Проверка на надписа преди запис=>Добра практика','Важното е надписът да се различава ясно от фона.'],
['Преобразуване и печат на изображение','Избраната област може да се копира, премества, завърта или оразмерява. Пропорционалното оразмеряване пази формата. Прегледът преди печат показва как ще изглежда листът.','Копирай нарисувано листо три пъти, завърти копията и направи рамка. Разгледай прегледа за печат, без да печаташ.','match','Коя операция ти трябва?','Обърнато листо=>Завъртане~По-малко листо без деформация=>Пропорционално оразмеряване~Още едно листо=>Копиране~Проверка на разположението върху лист=>Преглед преди печат','Преди истински печат проверяваме и правилния принтер.']]);
addResources(5,'Компютърно моделиране със Scratch',[
['Рисуване с Молив и повторения','Разширението Молив рисува при движение със спуснат молив. За квадрат използваме четири страни и четири завоя по 90°. Вдигнатият молив позволява преместване без линия.','Начертай квадрат със страна 80 стъпки. Добави втори квадрат на друго място, без свързваща линия.','number','Пресметни при рисуване с Молив.','Брой повторения за квадрат=>4~Завой при квадрат в градуси=>90~Завой при равностранен триъгълник в градуси=>120','За триъгълника използваме външния завой, а не вътрешния ъгъл.'],
['Собствени блокове и параметри','Собственият блок именува поредица за многократно използване. Параметърът подава стойност, например страна на квадрат. Промяната в дефиницията влияе на всички извиквания.','Създай блок „квадрат със страна s“. Извикай го с 40, 70 и 100. Вдигай молива при преместване между фигурите.','match','Свържи понятие и роля.','Дефиниция=>Описва действията на блока~Извикване=>Стартира блока~Числов параметър=>Подава размер~Булев параметър=>Подава вярно или невярно','Името на параметъра не е фиксирана стойност.'],
['Сложни фигури и подобряване на проект','Сложната рисунка може да се раздели на прости части. Подпрограмите улесняват проверката и повторната употреба. Тестваме първо отделните части и после цялото изображение.','Направи блокове „къща“ и „дърво“. Създай улица от три къщи и две дървета с различни позиции.','order','Подреди работата по сложна фигура.','Разделям рисунката на части~Създавам блок за всяка повтаряща се част~Тествам отделните блокове~Комбинирам ги в обща рисунка~Проверявам и премахвам нежеланите линии','Вдигай молива, когато се местиш между части.']]);
addResources(5,'Компютърна текстообработка',[
['Текст, редактиране и форматиране','Редактирането променя съдържание; форматирането променя вида. Абзацът се завършва с Enter. Интервалите не са надежден начин за центриране на заглавие.','Напиши покана за еко изложба с заглавие и два абзаца. Поправи грешките и центрирай заглавието с команда за подравняване.','match','Редактиране или форматиране?','Поправям сгрешена дума=>Редактиране~Изтривам излишно изречение=>Редактиране~Правя заглавието удебелено=>Форматиране~Центрирам абзац=>Форматиране','Питай се дали сменяш думите, или начина, по който изглеждат.'],
['Шрифт, абзац и запис на документ','Избираме четим шрифт, подходящ размер и ясно подравняване. Записваме работния файл във формат за редактиране. Експортът в PDF е отделна стъпка, когато искаме устойчив изглед за споделяне.','Оформи поканата с заглавие 18 pt и основен текст 12 pt. Запази работен документ и провери дали отново се отваря.','match','Свържи настройката с ефекта.','Размер на шрифта=>Големина на знаците~Bold=>Удебеляване~Подравняване=>Положение на абзаца~Междуредие=>Разстояние между редовете','Разстоянието между редовете не е размер на буквите.']]);
addResources(5,'Електронни таблици',[
['Клетки, редове и колони','Клетката е пресечна точка на ред и колона. Адресът A1 съдържа буква на колона и номер на ред. Данните могат да бъдат текст, числа или формули.','Създай таблица „Материали“ с колони за име, брой и цена. Въведи три реда и посочи адреса на всяка цена.','match','Свържи адреса с описанието.','A1=>Колона A, ред 1~B3=>Колона B, ред 3~C2=>Колона C, ред 2~D5=>Колона D, ред 5','Първо е колоната, после редът.'],
['Изчисления и визуализиране на данни','Формулата започва със знак =. За стойност умножаваме количество по единична цена. При промяна на входните данни формулата преизчислява резултата. Диаграмата помага да сравним стойности.','В работилницата за бюджет избери по един от трите материала и вмести сумата в 20 евро. После увеличи една цена и проследи резултата.','number','Пресметни бюджета.','3 картона по 2 евро=>6~2 лепила по 4 евро=>8~Обща стойност на предните две покупки=>14','Умножавай за всеки ред, после събери стойностите.']]);
addResources(5,'Компютърна презентация',[
['Слайд, оформление и представяне','Презентацията има ясна последователност и кратки текстове. Всеки слайд носи основно послание. Четимостта и подходящите изображения са по-важни от голям брой ефекти.','Направи три слайда: заглавие на еко изложба, какво сте създали и покана с дата и място. Представи ги за една минута.','order','Подреди представянето.','Казвам темата и целта~Показвам основните идеи и примери~Обобщавам и отправям покана~Отговарям на въпроси','Не започваме с въпроси преди зрителите да знаят темата.']]);
addResources(6,'Операционна система и носители на информация',[
['Бит, байт и мерни единици','Един байт съдържа 8 бита. В десетичната система 1 kB е 1000 B, а 1 MB е 1000 kB. В двоичната система 1 KiB е 1024 B, а 1 MiB е 1024 KiB. В задачите трябва да е ясно коя система се използва.','Сравни 2 MB и 2 MiB в байтове. Направи таблица с ясно изписани единици.','number','Използвай точно посочената единица.','3 байта в битове=>24~2 kB в байтове=>2000~2 KiB в байтове=>2048~3 MiB в KiB=>3072','Не смесвай десетични MB с двоични MiB.'],
['Операционна система, носители и формати','Операционната система управлява файлове, приложения и устройства. Форматът на файл определя организацията на съдържанието. Разширението подсказва формата, но само преименуване не извършва преобразуване.','Покажи разширенията на четири собствени учебни файла. Сравни изгледи „списък“ и „големи икони“.','match','Избери вид съдържание.','snimka.jpg=>Изображение~glas.mp3=>Звук~urok.mp4=>Видео~otchet.docx=>Текстов документ','Разширението след последната точка дава важна подсказка.']]);
addResources(6,'Компютърна текстообработка',[
['Символи и специални знаци','Някои знаци се въвеждат от клавиатурата, а други чрез меню за символи. Важни са правилният знак и контекстът: ° показва градус, а © обозначава авторско право.','Напиши кратък текст с 20 °C, © и знак €. Използвай менюто за символи за поне един от тях.','match','Свържи знака с употребата.','°=>Градус~€=>Евро~©=>Авторско право~@=>Част от имейл адрес','Подбирай символа по значение, а не само по външен вид.'],
['Изображение в текстов документ','Изображението може да е в реда с текста или с обтичане. Пазим пропорциите и избираме размер, който не измества важна информация. Добавяме смислен надпис и източник.','Създай едностраничен текст за растение със собствена снимка. Изпробвай две разположения на изображението и избери по-четимото.','order','Подреди работата с изображение.','Избирам разрешено изображение~Вмъквам го в документа~Оразмерявам пропорционално~Настройвам обтичането~Добавям надпис и източник','Разположението се настройва след вмъкването.'],
['Търсене, замяна и помощ','Търсенето намира съвпадения, а замяната променя текста. Проверяваме обхвата, за да не подменим части от други думи. Помощната система обяснява конкретни команди.','Напиши три изречения с думата „проект“. Замени я с „инициатива“, като прегледаш всяка промяна. Намери помощ за номерация на страници.','match','Свържи целта с командата.','Намирам дума=>Търсене~Подменям избран текст=>Замяна~Научавам за непозната команда=>Помощ~Отменям грешна замяна=>Undo','При голям документ не използвай „Замени всички“ без проверка.'],
['Страница, номерация и печат','Размерът, ориентацията и полетата определят мястото за съдържание. Номерацията помага за подредбата на многостраничен документ. Преди печат проверяваме принтер, страници и копия.','Оформи документ от две страници с номерация. В прегледа избери само втората страница, без да стартираш печат.','number','Пресметни броя отпечатани страници при едностранен печат.','Страници 2–4, едно копие=>3~Страници 1 и 3, две копия=>4~Документ от 5 страници, три копия=>15','Диапазонът 2–4 включва 2, 3 и 4.']]);
addResources(6,'Обработка на таблични данни',[
['Типове и формати на данни','Число, текст и дата имат различна роля. Форматирането променя представянето: 0,25 може да се показва като 25%. Идентификатор с водеща нула обикновено се съхранява като текст.','Създай колони „Код“, „Количество“, „Цена“, „Дата“ и „Отстъпка“. Въведи измислени данни и избери подходящи формати.','match','Свържи стойността с подходящото представяне.','Единична цена=>Валутен формат~Отстъпка 0,10=>Процент 10%~Код 0012=>Текст~Ден на доставка=>Дата','Процентният формат умножава показаната стойност по 100.'],
['Формули и ред на действията','Формулата започва с =. Скобите определят приоритет, а умножението се изпълнява преди събирането. Адресите на клетки позволяват резултатът да се обнови при промяна на данните.','Въведи количество в B2 и цена в C2. Изчисли =B2*C2, после промени количеството и провери резултата.','number','Пресметни формулите.','=2+3*4=>14~=(2+3)*4=>20~=18/3+2=>8','Изчисли първо скобите, после умножение и деление.'],
['SUM, AVERAGE, MIN и MAX','SUM сумира, AVERAGE намира средноаритметично, MIN — най-малката, MAX — най-голямата числова стойност. Областта B2:B5 включва всички клетки между двата края.','Въведи 4, 6, 8 и 10 в B2:B5. Използвай четирите функции и сравни с ръчно пресмятане.','number','За числата 4, 6, 8 и 10 намери:','SUM=>28~AVERAGE=>7~MIN=>4~MAX=>10','Средноаритметичното е сумата, разделена на броя числа.'],
['Печат на таблица','Областта за печат избира нужните клетки. Ориентацията и мащабът влияят дали таблицата ще се събере. Прекалено силното намаляване може да направи текста нечетим.','Подготви широка таблица за печат в пейзажна ориентация. Провери дали заглавията и последната колона се виждат.','order','Подреди подготовката за печат.','Избирам нужната област~Настройвам ориентация и полета~Настройвам подходящ мащаб~Преглеждам четимостта и броя страници~Избирам правилния принтер при разрешен печат','Печатът не е заместител на прегледа.']]);
addResources(6,'Работа с графични изображения',[
['Растер, вектор и файлови формати','Растерната графика използва пиксели, а векторната — описания на обекти. JPEG е подходящ за много снимки, PNG поддържа прозрачност, SVG е векторен формат. Изборът зависи от предназначението.','Сравни снимка и векторна икона при увеличение. Запази собствено изображение в два формата и сравни размерите на файловете.','match','Избери подходящ формат или вид.','Лого с мащабиране=>SVG~Снимка с много цветови преходи=>JPEG~Растерна икона с прозрачност=>PNG~Изображение от пиксели=>Растер','Преобразуването от JPEG в PNG не възстановява изгубени детайли.'],
['Дигитализиране и разделителна способност','Камера или скенер превръща физическо изображение в дигитално. Размерите в пиксели определят броя пиксели, а не автоматично качеството. Добрата светлина и фокусът са важни още при заснемането.','Снимай собствена рисунка при добро осветление. Прехвърли файла по указание, изрежи фона и запази отделно копие.','number','Пресметни броя пиксели.','Изображение 100 × 100=>10000~Изображение 200 × 100=>20000~Изображение 20 × 30=>600','Умножи ширината по височината.'],
['Изрязване, яркост, контраст и размер','Изрязването премахва краищата. Яркостта променя светлотата, а контрастът — различието между светли и тъмни части. Намаляването на размерите е различно от изрязване.','Направи три копия на собствена снимка: изрязано, с променена яркост и с намалена ширина. Сравни ефектите.','match','Кой инструмент е нужен?','Премахвам излишен край=>Изрязване~Изсветлявам цялата снимка=>Яркост~Подчертавам светло и тъмно=>Контраст~Намалявам ширината в пиксели=>Промяна на размер','Работи върху копие, за да запазиш оригинала.']]);
addResources(6,'Компютърна презентация',[
['Звук, анимации и преходи','Анимацията засяга обект в слайда, а преходът — смяната между слайдове. Звуците и ефектите трябва да подкрепят съдържанието. Проверяваме времетраене и начин на стартиране.','Създай три слайда за природен обект. Добави умерен преход и една анимация; тествай дали не пречат на обяснението.','match','Каква настройка е нужна?','Плавна смяна на слайд=>Преход~Поява на надпис=>Анимация на обект~Колко дълго се вижда слайдът=>Времетраене~Аудио към разказа=>Звуков файл','Не всеки ефект помага за разбиране.'],
['Формати, печат и представяне','Работният файл запазва възможности за редакция. Експортът в PDF пази страници, но не възпроизвежда анимациите. При представяне използваме слайдовете като опора, а не четем всеки ред.','Запази презентация като работен файл и PDF. Отвори двата варианта и сравни. Подготви едноминутно устно обяснение.','match','Свържи целта с избора.','Редактиране на слайдове=>Работен презентационен файл~Статични страници за споделяне=>PDF~Няколко слайда на лист=>Настройки за разпечатки~Проверка на темпо и говор=>Репетиция','Провери експортирания файл, а не само командата за запис.']]);
addResources(6,'Интернет и интегриране на дейности',[
['Достъп до интернет и комуникация','Интернет свързва мрежи. Wi-Fi е начин за безжична връзка в локална мрежа и не гарантира сам по себе си интернет. Синхронната комуникация е в реално време; асинхронната не изисква едновременно участие.','Направи таблица с примери за разговор в реално време и за съобщение, което получателят чете по-късно.','match','Синхронна или асинхронна комуникация?','Видеоразговор на живо=>Синхронна~Разговор с глас на живо=>Синхронна~Електронно писмо=>Асинхронна~Публикация във форум=>Асинхронна','Съобщението в чат може да се прочете по-късно; тук сравняваме конкретно зададените примери.'],
['Лицензи, цитиране и интегриран документ','Лицензът описва позволеното използване. Creative Commons има различни варианти за съдържание; GPL се отнася до софтуер. Интегрираният документ съчетава текст и други обекти с ясни източници.','Създай страница за природен обект със собствен текст, разрешено изображение и списък на източниците. Посочи автор, заглавие, адрес и дата на достъп.','match','Свържи означението с основния смисъл.','CC BY=>Посочване на автор~CC BY-SA=>Автор и споделяне при същия лиценз~CC BY-NC=>Автор и ограничение за некомерсиална употреба~GPL=>Лиценз за свободен софтуер','Провери пълните условия на конкретния лиценз, преди да използваш материал.']]);
addResources(6,'Компютърно моделиране с Python',[
['От блокове към текстов код','Текстовата програма записва инструкциите със синтаксис на език. В Python отстъпите имат значение. Променливите пазят стойности, input чете текст, а print извежда резултат.','Напиши програма, която пита за измислено име и отпечатва поздрав. После прочети цяло число чрез int(input()) и изведи следващото число.','number','Проследи резултата от фрагментите.','x = 3; x = x + 2; print(x)=>5~a = 4; print(a * 3)=>12~print(10 - 6)=>4','Тук точката и запетаята разделя последователни инструкции на един ред.'],
['Условия и повторения в текстов език','Условният оператор избира действие. Цикълът повтаря инструкции. В Python range(4) дава четири стойности: 0, 1, 2 и 3. Отстъпът показва кои инструкции принадлежат на конструкцията.','Напиши програма, която четири пъти извежда „Пази природата“. Добави проверка дали въведено число е положително.','number','Колко пъти ще се повтори тялото на цикъла?','for i in range(3)=>3~for i in range(5)=>5~for i in range(0)=>0','range(n) без допълнителни аргументи дава n стойности за неотрицателно цяло n.'],
['Графика, случайност и библиотеки','Библиотеката предоставя готови функции. Модулът turtle позволява рисуване чрез движение и завои. random може да избира случайни стойности. Проверяваме документацията за точните параметри.','С turtle начертай квадрат. Направи функция за квадрат със страна като параметър и я извикай на различни позиции.','match','Свържи Python средство с ролята.','import turtle=>Зареждане на модул за рисуване~forward(50)=>Движение напред~right(90)=>Завой надясно~penup()=>Преместване без рисуване','Командите са методи на turtle или на създаден обект според начина на импорт.'],
['Анимационен проект със скриптов език','Сценарият се разделя на обекти и действия. Функциите обединяват повторно използваем код. При анимация проверяваме началното състояние, промените и начина за спиране.','Създай с избраната от учителя Python среда движещ се герой или променяща се рисунка. Опиши сценария и демонстрирай работещ вариант.','order','Подреди разработката на анимацията.','Описвам сценария~Разделям го на обекти и действия~Избирам библиотека и създавам кода~Тествам движението и края~Представям и обяснявам решението','Първо направи един работещ елемент, после добавяй останалите.']]);
addResources(7,'Компютърна система и защита на данните',[
['Компоненти и технически параметри','Процесорът изпълнява инструкции, RAM държи работни данни, а SSD съхранява файлове. Производителността зависи от съчетанието на компоненти и задачата; една по-висока честота не гарантира по-бърз компютър във всички случаи.','Сравни две примерни конфигурации по процесор, RAM, място за файлове и предназначение. Обоснови избор за обработка на видео.','match','Свържи компонент и роля.','CPU=>Изпълнява инструкции~RAM=>Работна памет~SSD=>Съхранява файлове~Мрежова карта=>Свързва към мрежа','Разграничи работната памет от дълготрайното съхранение.'],
['Зловреден софтуер и защита','Защитата съчетава актуализации, проверени източници, антивирусен софтуер и резервни копия. Нито едно средство не гарантира пълна защита. При съмнителен файл прекъсваме действието и уведомяваме отговорния възрастен.','Направи план за защита на учебен компютър. Посочи как се възстановява важен файл след загуба. Не изтегляй пробни вируси.','match','Избери подходящата мярка.','Загуба на файл=>Резервно копие~Известна уязвимост=>Актуализация~Непознато приложение=>Проверка на източника~Съмнителен прикачен файл=>Не го отварям и търся помощ','Антивирусната програма не заменя резервното копие.']]);
addResources(7,'Компютърна текстообработка',[
['Таблици и работа с няколко документа','Таблицата подрежда съдържание в редове и колони. Обединяването създава обща клетка, а разделянето я разбива. При копиране между документи проверяваме дали форматирането е подходящо за новия документ.','Създай програма за изложба с колони час, дейност и отговорник. Обедини горния ред за заглавие. Прехвърли текста от втори документ.','match','Свържи цел и операция.','Общо заглавие над три колони=>Обединяване на клетки~Още една дейност=>Вмъкване на ред~Два елемента в една разделена клетка=>Разделяне на клетка~Подчертаване на заглавния ред=>Фон и форматиране','Редакцията на структурата е различна от промяна на цветовете.']]);
addResources(7,'Обработка на таблични данни',[
['Проектиране и форматиране на електронна таблица','Планираме колоните според данните, използваме ясен заглавен ред и еднакви формати. Многоредовият текст помага при дълги заглавия. Обединени клетки в област с данни могат да затруднят сортиране.','Създай таблица за заемани книги с код, заглавие, брой и дата. Не използвай истински лични данни.','match','Свържи нуждата с настройката.','Дълго заглавие в тясна колона=>Пренасяне на текст~Цена с два знака=>Числов или валутен формат~Еднаква структура на записите=>Едни и същи колони~Ясен смисъл на данните=>Заглавен ред','Форматирането трябва да улеснява четенето и обработката.'],
['Относителни, абсолютни и смесени адреси','При копиране относителният адрес се променя. Знакът $ фиксира колона, ред или и двете. $B$1 остава същият, $B1 фиксира колона B, а B$1 — ред 1.','Създай таблица за цени и общ коефициент в B1. Копирай формула, която умножава цената по $B$1, и обясни защо го фиксираш.','match','Какъв е видът на адреса?','A2=>Относителен~$A$2=>Абсолютен~$A2=>Смесен: фиксирана колона~A$2=>Смесен: фиксиран ред','Доларът фиксира елемента непосредствено след него.'],
['Сортиране, търсене и замяна','Сортирането подрежда записи по критерий. Избираме цялата таблица, за да не разменим връзката между имената и стойностите. Търсенето намира, а замяната редактира съвпаденията.','Създай пет измислени продукта с цени. Сортирай възходящо по цена и провери дали всеки продукт е останал със своята цена.','order','Подреди числата възходящо.','3~8~12~21','Възходящо означава от най-малкото към най-голямото.'],
['Диаграми и интерпретация','Колонната диаграма сравнява категории, линейната показва промяна, а кръговата — части от цяло при подходящи данни. Заглавието, единиците и легендата помагат за правилно тълкуване.','Начертай диаграма за събрана хартия през четири седмици. Избери тип, означи килограмите и напиши два извода.','match','Избери подходящ тип за зададената цел.','Сравнение на три класа=>Колонна~Температура по дни=>Линейна~Дялове от общ бюджет=>Кръгова~Описание на цветовете=>Легенда','Изводът трябва да следва от данните, а не само от вида на диаграмата.']]);
addResources(7,'Компютърно моделиране',[
['Типове данни в Python','Целите числа, реалните числа и текстовете имат различни операции. input връща текст; за числово пресмятане преобразуваме с int или float. „12“ и 12 не са еднакъв тип.','Напиши програма за цена и количество. Избери float за цена и int за брой. Изведи общата стойност.','match','Определи Python типа.','12=>int~3.5=>float~"12"=>str~"Робот"=>str','Кавичките означават текст, дори съдържанието да изглежда като число.'],
['Цикли for и while','for обхожда последователност, а while повтаря докато условието е вярно. Цикълът трябва да води към край, когато задачата го изисква. За натрупване създаваме начална стойност преди цикъла.','Намери сбора от 1 до 5 с цикъл. Сравни с ръчно пресмятане. Добави тест за сума до 0 според избраните входни условия.','number','Проследи повторенията и сборовете.','Брой стойности в range(1,5)=>4~Сбор на 1, 2, 3 и 4=>10~s=0; за числата 2, 4, 6 добавям към s. Резултат?=>12','Крайната граница на range не се включва.']]);
addResources(7,'Работа по проект',[
['Цел, екип, план и ресурси','Проектът решава конкретна задача. Планът съдържа дейности, роли и срокове. Разпределяме отговорностите и посочваме използваните източници. Следим напредъка, за да има време за тестове.','Планирайте „Дигитална карта на природните забележителности“ с три роли и срокове. Използвайте само подходящи публични сведения.','order','Подреди основните етапи.','Определяме проблем и резултат~Планираме роли и срокове~Събираме разрешени ресурси и разработваме~Тестваме и поправяме~Представяме продукта','Планирането е преди изпълнението.'],
['Интегриране на приложения и програмен проект','Данни от таблица могат да се използват в документ и презентация. Програмата може да обработи числа за проекта. При прехвърляне проверяваме точност, формати и съвместимост.','Обработете с Python пет стойности за събрани отпадъци. Направете диаграма в таблица и включете изводите в презентация.','match','Избери средство за всяка дейност.','Пресмятане на сбор с код=>Python~Диаграма на стойности=>Електронна таблица~Подробно описание на метода=>Текстов документ~Защита пред публика=>Презентация','Един проект може да използва няколко приложения с различна роля.'],
['Документация и защита','Документацията описва цел, средства, стъпки, проверки и източници. Защитата включва демонстрация и аргументи. Показваме реалния принос на всеки член на екипа.','Подгответе три слайда: проблем, решение и тестове. Всеки участник обяснява собствена задача и наученото от нея.','match','Свържи въпрос и доказателство.','Какво решава проектът?=>Цел и потребители~Работи ли?=>Тестове и демонстрация~Кой какво направи?=>Разпределение на ролите~Откъде са ресурсите?=>Списък на източниците','Красива презентация не заменя работещия продукт.']]);
addResources(7,'Звукова и видео информация',[
['Видеоклип от изображения и звук','Видеоредакторът подрежда кадри по времева линия. Продължителностите определят общото време. Звукът и надписите трябва да подкрепят посланието; проверяваме правата и съгласието за лица и гласове.','Създай 20-секунден клип от собствени рисунки с начало, надпис и край. Използвай разрешен звук и добави източника.','number','Пресметни продължителността без припокриване.','3 кадъра по 4 секунди=>12~5 секунди начало + 12 секунди съдържание + 3 секунди край=>20~30 секунди клип с изрязани 7 секунди=>23','Тук няма застъпващи се преходи; събираме или изваждаме времената.'],
['Редакция, ефекти и експорт','Работният проект и готовият видеофайл са различни. Експортът създава файл за гледане. Кодекът, размерите на кадъра и настройките влияят на обема и качеството. Проверяваме готовия файл на друго възпроизвеждащо приложение.','Експортирай учебния клип в два размера. Сравни четимостта на надписите и обема на файловете.','order','Подреди финализирането.','Преглеждам времевата линия~Проверявам надписи и звук~Избирам настройки за експорт~Експортирам видеофайла~Отварям готовия файл и проверявам','Запазеният проект не винаги се отваря като видео в плейър.']]);
addResources(7,'Компютърна презентация',[
['Вграждане на звук и видео','Мултимедийният обект може да е вграден или свързан според приложението. Проверяваме дали работи на компютъра за представяне. Настройката за начало определя кога се възпроизвежда.','Добави собствения клип в презентация. Запази я и провери възпроизвеждането след повторно отваряне.','match','Кое проверяваш?','Кога започва клипът=>Настройка за стартиране~Чува ли се говорът=>Сила и качество на звука~Работи ли на друг компютър=>Достъпност и съвместимост на медията~Колко дълго трае=>Продължителност','Тествай точно файла, който ще представяш.'],
['Диаграми, графични схеми и таблици','Избираме визуализация според смисъла: процес за последователни стъпки, йерархия за подчинени нива, диаграма за числови данни. Текстът трябва да остане четим при представяне.','Представи фазите на своя проект с процесна схема и резултатите с диаграма. Обясни защо избра различни визуализации.','match','Коя визуализация е подходяща?','Стъпки на рециклиране=>Процесна схема~Структура на екип=>Йерархична схема~Количество хартия по месеци=>Диаграма~Точни стойности за сравняване=>Таблица','Схемата показва отношения, а диаграмата представя данни.']]);
addResources(7,'Интернет и лична неприкосновеност',[
['Социални мрежи и защита на профила','Настройваме кой вижда публикациите, ограничаваме ненужни разрешения и използваме допълнителна защита. При злоупотреба пазим доказателство, докладваме и търсим помощ. Не отговаряме с нова обида.','Изработи план за реакция при фалшив профил, представящ се за ученик. Използвай измислен пример.','order','Подреди разумна реакция при злоупотреба.','Спирам взаимодействието с подозрителния профил~Запазвам наличното доказателство~Докладвам и блокирам чрез платформата~Търся подкрепа от доверен възрастен','Запази доказателството, преди да изгубиш достъп до съобщението.']]);
addResources(8,'Компютърни мрежи и услуги',[
['Социално общуване и съвместна работа','Споделените документи имат роли като читател, коментиращ и редактор. Даваме само нужните права и уточняваме правилата за работа. Публикуването носи отговорност към другите участници.','В учебна среда планирайте общ документ с редактори и читатели. Обяснете защо публичната връзка за редактиране не е нужна.','match','Избери най-ограничената достатъчна роля.','Само да прочете=>Читател~Да даде бележки=>Коментиращ~Да променя текста=>Редактор~Не е участник и няма нужда от файла=>Без достъп','Не предоставяй повече права, отколкото са необходими.'],
['Търсене по критерии и оценка на източници','Съставната заявка комбинира ключови думи, точни фрази и ограничения. Надеждността се оценява по автор, доказателства, дата и независими потвърждения. Популярност и достоверност са различни неща.','Потърси официални данни за защитена местност. Запиши заявката и сравни два резултата по четири критерия.','match','Свържи цел и средство.','Точна фраза=>Кавички в поддържаща ги търсачка~Търсене в конкретен домейн=>Оператор site:~Проверка на актуалност=>Дата на публикация~Проверка на твърдение=>Доказателства и независим източник','Операторите зависят от търсачката; проверявай резултатите, не само заявката.'],
['Онлайн сесия и киберсигурност','При онлайн среща проверяваме микрофон, камера и обхват на споделяне. Известията и отворените прозорци могат да разкрият лични данни. Записването се съобразява с разрешенията и правилата.','Подготви сценарий за учебна онлайн среща. Избери да споделиш само необходимия прозорец и обясни защо.','order','Подреди подготовката за представяне онлайн.','Затварям ненужни лични прозорци~Проверявам микрофон и звук~Избирам правилния прозорец за споделяне~Проверявам какво виждат участниците~Започвам представянето','Проверявай обхвата на споделяне преди да покажеш съдържание.']]);
addResources(8,'Компютърни системи',[
['История и принципи на компютрите','Компютърните системи се развиват чрез промени в електронните елементи, паметта и начините за взаимодействие. Съвременните устройства продължават да въвеждат, обработват, съхраняват и извеждат данни.','Направи времева линия с четири проверени събития от историята на компютрите. Посочи източниците и избегни спорни твърдения за „единствен първи компютър“.','order','Подреди елементната база в обичайната историческа последователност.','Електронни лампи~Транзистори~Интегрални схеми~Микропроцесори','Това е опростена последователност за сравнение на технологиите.'],
['Конфигурации и периферни устройства','Компонентите се избират според задачата и съвместимостта. Капацитетът на SSD и размерът на RAM описват различни неща. Комуникационните устройства осигуряват обмен на данни.','Предложи конфигурация за учебен кабинет. Обясни избора на памет, съхранение, монитор и мрежова свързаност без да посочваш актуални цени.','match','Свържи параметъра с компонента.','16 GB работна памет=>RAM~512 GB място за файлове=>SSD~Резолюция 1920 × 1080=>Монитор~Ethernet порт=>Мрежова връзка','Еднаквата мерна единица не означава еднакво предназначение.'],
['Системен и приложен софтуер','Системният софтуер осигурява работата на компютъра. Приложният изпълнява конкретни задачи. Операционната система управлява ресурси, файлове и приложения; драйверите подпомагат работата на устройства.','Състави списък с използваната операционна система и три приложения. Посочи ролята на всяко.','match','Определи вида.','Операционна система=>Системен~Драйвер за принтер=>Системен~Текстов редактор=>Приложен~Видеоредактор=>Приложен','Ролята на програмата определя класификацията.'],
['Мобилни устройства и прехвърляне на данни','Мобилната операционна система определя съвместимите приложения и разрешения. Wi-Fi, мобилна мрежа, Bluetooth и USB имат различни роли. Прехвърляме само необходимите файлове и проверяваме получателя.','Опиши два начина да прехвърлиш собствена рисунка между телефон и компютър. Сравни нуждата от кабел и интернет.','match','Свържи средство и употреба.','USB=>Кабелно прехвърляне при поддръжка~Bluetooth=>Късо безжично разстояние~Wi-Fi=>Връзка с локална безжична мрежа~Мобилни данни=>Връзка чрез мобилен оператор','Наличието на Wi-Fi не доказва достъп до интернет.']]);
addResources(8,'Приложни програми',[
['Инсталиране, актуализиране и помощ','Изтегляме софтуер от проверен официален източник и проверяваме съвместимостта. Актуализациите често поправят уязвимости. На училищен компютър инсталацията се извършва според указанията на администратора.','Избери приложение и намери официалната му помощ. Запиши системните изисквания и начина за актуализиране, без да инсталираш самостоятелно.','order','Подреди проверката преди инсталиране в учебна среда.','Уточнявам нуждата и разрешението~Проверявам официалния източник~Сравнявам системните изисквания~Преглеждам нужните разрешения~Следвам указанията на администратора','Рекламният бутон за изтегляне може да не принадлежи на официалния продукт.'],
['Архивиране и компресиране','Архивът обединява файлове и може да използва компресиране. Резервното копие има друга цел — възстановяване при загуба. Вече компресирани снимки или видео може да не намалеят значително в ZIP.','Създай ZIP архив на три собствени учебни файла. Разархивирай в нова папка и провери дали файловете се отварят.','order','Подреди проверка на архив.','Избирам учебните файлове~Създавам архив~Разархивирам в отделна папка~Отварям възстановените файлове~Сравнявам съдържанието с оригиналите','Архивът трябва да се тества, а не само да се създаде.'],
['Технически проблеми и диагностика','Отстраняването на проблем започва с описание на симптома. Проверяваме най-простите причини и променяме по едно нещо. Не изключваме защити или не изтриваме данни като първа стъпка.','Състави план за случай „няма звук в презентацията“. Включи проверки на сила на звука, правилно изходно устройство и друг аудиофайл.','match','Коя проверка е подходяща?','Няма звук=>Изходно устройство и сила~Файлът не се отваря=>Формат и съвместимо приложение~Няма интернет само на едно устройство=>Локална връзка и настройки~Принтерът печата другаде=>Избраният принтер','Запиши точния симптом преди да търсиш решение.']]);
addResources(8,'Програмиране и изкуствен интелект',[
['Програмни инструкции и интерпретатор','Скриптовият език позволява да опишем решение като програма. Интерпретаторът изпълнява кода според правилата на езика. Вградените функции предоставят готови операции.','Напиши Python програма за лице на правоъгълник с две входни стойности. Провери с размери 3 и 4 и с 5 и 2.','number','Проследи резултата.','print(3 * 4)=>12~print(len("robot"))=>5~print(max(2, 8, 5))=>8','len брои елементите на низа, а max избира най-голямата стойност.'],
['AI, персонализиране и заявки','AI системите могат да разпознават закономерности или да генерират съдържание. Ясната заявка описва цел, контекст и очакван формат. Полученият отговор трябва да се провери, особено при фактически твърдения.','Състави заявка за три идеи за еко плакат за ученици. Задай възраст, дължина и формат. Сравни резултата с изискванията.','match','Свържи частта на заявката с ролята.','За ученици в 8. клас=>Аудитория~Предложи идеи за еко плакат=>Задача~Три кратки предложения=>Формат и обем~Без лични данни=>Ограничение','Конкретната заявка улеснява оценката на отговора.'],
['Данни, разрешения и дълбоки фалшификации','Публичните снимки и записи могат да се използват за обучение или манипулиране според услугата. Не можем надеждно да докажем истинност само по външен вид. Проверяваме произход, контекст и независими потвърждения.','Анализирай измислен случай с необичаен видеозапис. Направи списък с проверки, без да качваш лица или гласове на реални ученици.','match','Свържи риска с подходящата реакция.','Непознато приложение иска всички снимки=>Проверявам нуждата и разрешенията~Сензационно видео=>Търся първоизточник~AI дава непознат факт=>Проверявам независимо~Искат лични данни за учебна заявка=>Използвам измислени или обобщени данни','Липсата на видими дефекти не доказва, че видеото е истинско.']]);
addResources(8,'Създаване и публикуване на информация в интернет',[
['Структура, HTML и хипервръзки','HTML описва структурата на страницата. Заглавията, абзаците, изображенията и връзките имат различни елементи. Навигацията трябва да показва ясно как посетителят достига съдържанието.','Създай локална страница с заглавие, два абзаца и връзка към втора учебна страница. Използвай собствени текстове.','match','Свържи HTML елемента с ролята.','h1=>Основно заглавие~p=>Абзац~a=>Хипервръзка~img=>Изображение','HTML задава смислена структура; CSS определя много от визуалните свойства.'],
['Дизайн, медия и достъпност','Четимият контраст, ясните връзки и навигацията с клавиатура улесняват посетителите. Смисленият алтернативен текст описва изображението за хора, които не го виждат. Не вграждаме чужда медия без разрешение.','Прегледай учебна страница само с Tab и Enter. Поправи неясно име на връзка и добави описание на смислено изображение.','match','Свържи нуждата с решението.','Изображението не се вижда=>Алтернативен текст~Работа без мишка=>Клавиатурна навигация~Трудно четим текст=>По-добър контраст~Неясна връзка „тук“=>Описателно име','Достъпността е част от работещия дизайн.'],
['Домейн, хостинг и HTTPS','Домейнът е име за достъп, а хостингът предоставя място и обслужване. HTTPS защитава преноса и удостоверява домейна чрез сертификат, но не доказва истинността на всяко твърдение в сайта.','Начертай схема браузър–домейн–уебсървър. Обясни какво трябва да се качи, за да се отвори статична страница онлайн.','match','Свържи понятие и смисъл.','Домейн=>Име на сайта~Хостинг=>Среда за публикуване~Уебсървър=>Обслужва уебзаявки~HTTPS=>Защитен пренос към удостоверен домейн','Катинарът не е оценка за качеството на съдържанието.'],
['Публикуване и отговорност','Преди публикуване проверяваме съдържание, навигация, лични данни, права и изглед на различни устройства. След качване отваряме публичния адрес и проверяваме реалния резултат.','Подготви учебен сайт с три страници за природна тема. Направи списък с проверки преди публикуване и демонстрирай локалния вариант.','order','Подреди публикуването.','Проверявам съдържание и права~Проверявам връзки и изглед~Качвам файловете в разрешения хостинг~Отварям публичния адрес~Тествам публикуваните страници','Публикуваната версия може да се различава от локалната.']]);
addResources(8,'Работа по проект',[
['Екипен уебпроект и защита','Екипът планира страници, роли и общ стил. Събира разрешени ресурси, разработва и тества. Защитата обяснява потребителите, избора на решения и резултатите от тестовете.','Разработете сайт „Дигитални навици“ с начална страница, съвети и ресурси. Разпределете роли и представете как сте проверили качеството.','order','Подреди работата.','Определяме аудиторията и целта~Планираме структура и роли~Създаваме съдържание и страници~Тестваме навигация и достъпност~Представяме и защитаваме решенията','Всеки член на екипа трябва да може да обясни своя принос.']]);
addResources(9,'Компютърни системи и глобално позициониране',[
['Мобилни технологии и обмен на данни','Мобилните устройства съчетават изчисления, сензори и комуникации. За различни задачи се използват различни връзки. Изборът зависи от разстояние, съвместимост, скорост и нужда от интернет.','Сравни USB, Bluetooth, Wi-Fi и мобилни данни за прехвърляне на собствен учебен клип. Посочи предимство и ограничение.','match','Свържи ситуация и подходящо средство.','Кабел между телефон и компютър=>USB~Безжични слушалки наблизо=>Bluetooth~Връзка към училищен рутер=>Wi-Fi~Интернет през оператор извън Wi-Fi=>Мобилни данни','Начинът за свързване и наличието на интернет са отделни въпроси.'],
['GPS и системи за глобално позициониране','Приемникът определя позицията чрез сигнали от спътници. За самото изчисляване не е задължителен интернет, но онлайн картите и актуалният трафик могат да го изискват. Помощни мрежови данни могат да ускорят първоначалното определяне.','Обясни разликата между позициониране и зареждане на карта. Планирай маршрут с предварително изтеглена карта, без да споделяш личен адрес.','match','Нужен ли е непременно интернет за точно зададеното действие?','Приемане на спътникови сигнали=>Не~Определяне на позиция от приемник=>Не~Зареждане на неизтеглена онлайн карта=>Да~Получаване на актуален онлайн трафик=>Да','Тук разграничаваме спътниковата функция от онлайн услугите.']]);
addResources(9,'Компютърни мрежи и защита',[
['Локални мрежи, устройства и среди','Комутаторът свързва устройства в локална мрежа, а маршрутизаторът насочва трафик между мрежи. Точката за достъп осигурява безжично присъединяване. Кабелните и безжичните среди имат различни свойства.','Начертай малка мрежа с три компютъра, комутатор, рутер и точка за достъп. Обясни ролята на всяко устройство.','match','Свържи функция и устройство.','Свързва компютри в LAN=>Комутатор~Насочва между мрежи=>Маршрутизатор~Осигурява Wi-Fi достъп=>Точка за достъп~Свързва конкретния компютър към мрежата=>Мрежова карта','Домашният рутер често съчетава няколко от тези функции.'],
['IP, домейни и протоколи','IP адресът се използва за адресиране в мрежата. DNS свързва домейн с нужните мрежови записи. Протоколът определя правила за обмен. HTTPS, SMTP и други протоколи имат различно предназначение.','Проследи с думи как браузърът намира страница по домейн. Не променяй мрежови настройки на училищния компютър.','match','Свържи понятие и роля.','IP адрес=>Адресиране в мрежа~DNS=>Разрешаване на домейн имена~HTTPS=>Защитен уебобмен~SMTP=>Предаване на електронна поща','Домейнът е име; IP адресът е част от мрежовото адресиране.'],
['Споделяне и права за достъп','Локално, мрежово и облачно съхранение имат различна достъпност. Даваме минимални нужни права. Редакторът може да промени съдържание, затова правото не трябва да се предоставя автоматично на всички.','Проектирайте споделена папка за екипен проект. Уточнете кой редактира, кой чете и къде се пази резервно копие.','match','Избери действие.','Съученик трябва само да прочете=>Давам право за четене~Екипен автор трябва да поправя=>Давам право за редактиране~Външен човек няма нужда=>Не предоставям достъп~Важна финална версия=>Създавам резервно копие','Облачният файл не е автоматично публичен или автоматично защитен.'],
['Фишинг, бисквитки и дигитална идентичност','Фишингът подмамва към разкриване на тайни или опасни действия. Проверяваме подателя и адреса независимо от логото. Бисквитките съхраняват информация за взаимодействието със сайт; следим разрешенията и поверителността.','Разгледай измислен имейл „Спешно потвърди паролата“. Назови три предупредителни сигнала и безопасен начин за проверка чрез познат официален канал.','order','Подреди реакцията при подозрително съобщение.','Не отварям връзката и приложението~Проверявам подателя и контекста~Влизам независимо през познат официален адрес~Докладвам по установения ред','Не използвай контактите в самото съмнително съобщение за единствена проверка.']]);
addResources(9,'Интернет услуги и електронна търговия',[
['Електронни услуги, идентификация и подписи','Електронните услуги могат да изискват удостоверяване на самоличност. Цифровият сертификат и електронният подпис имат конкретни технически и правни роли. За упражнение използваме симулации и измислени данни.','Намери официална публична страница, описваща електронна услуга. Запиши целта, нужния вид идентификация и адреса; не подавай реално заявление.','match','Свържи средство и основна функция.','Двуфакторно удостоверяване=>Допълнителна проверка при вход~Цифров сертификат=>Свързва ключ с удостоверени данни~Електронен подпис=>Подписване на електронни данни~Официален портал=>Достъп до публични услуги','Конкретните изисквания се проверяват в описанието на услугата.'],
['Електронни покупки и разплащания','Преди поръчка проверяваме търговеца, общата цена, доставката и условията. Не предоставяме кодове за потвърждение на други хора. Учебното упражнение не изисква реално плащане или банкова информация.','Сравни две измислени оферти за учебен комплект с доставка. Избери по-ниската обща цена и посочи какви данни би проверил за търговеца.','number','Пресметни общата цена в евро.','Стока 18 + доставка 4=>22~Стока 20 + безплатна доставка=>20~Две стоки по 9 + една доставка 3=>21','Сравнявай общата стойност, а не само цената на стоката.']]);
addResources(9,'Приложни програми',[
['Шаблони, теми и формуляри','Шаблонът задава повторно използваема структура. Темата управлява съгласуван стил. Формулярът събира структурирани данни чрез полета с ясни указания. Събираме само нужната информация.','Създай шаблон за покана без лични имена и формуляр за избор на учебна дейност. Използвай измислени записи.','match','Свържи нужда и средство.','Повтаряща се структура на покана=>Шаблон~Съгласувани шрифтове и цветове=>Тема~Попълване на определени полета=>Формуляр~Проверка на готовия документ=>Преглед','Шаблонът може да съдържа структура и стил, но не замества конкретното съдържание.'],
['Циркулярни писма','Циркулярното писмо съчетава общ документ с записи от източник на данни. Полетата се заменят със стойности за всеки получател. Прегледът проверява дали данните попадат на правилните места.','Направи списък с три измислени героя и предпочитани дейности. Създай персонализирана учебна покана и прегледай трите варианта, без да ги изпращаш.','order','Подреди циркулярното писмо.','Подготвям таблицата с измислени записи~Създавам основния документ~Свързвам източника на данни~Вмъквам полетата~Преглеждам всеки резултат~Генерирам документите без реално изпращане','Не пропускай проверката на индивидуалните резултати.'],
['Валидиране и ограничения на данните','Валидирането ограничава допустимите стойности, например цяло число от 1 до 10. То намалява грешките, но не доказва, че въведеното отразява реалността. Полезни са ясни съобщения и тестове по границите.','Създай колона с брой места от 1 до 10. Тествай 0, 1, 10 и 11 и запиши очакваното поведение.','match','За цяло число от 1 до 10 включително:','0=>Недопустимо~1=>Допустимо~10=>Допустимо~11=>Недопустимо','Провери и точно граничните стойности.'],
['Филтриране с комбинирани критерии','Филтърът показва записи, които отговарят на условия, без да изтрива останалите. Условието „и“ изисква изпълнение на двата критерия. Сортирането променя подредбата, а филтрирането — видимите записи.','Създай таблица с продукти, категория и цена. Покажи само книги с цена до 15 евро включително.','match','Критерий: категория Книга И цена ≤ 15.','Книга, 12 евро=>Показва се~Книга, 15 евро=>Показва се~Книга, 18 евро=>Скрива се~Играчка, 8 евро=>Скрива се','Ниската цена не е достатъчна, ако категорията не съвпада.'],
['Обобщаване и междинни пресмятания','Групираме записите по критерий и изчисляваме суми или брой. Междинните резултати се проверяват с общата сума. Входните данни трябва да имат ясни колони и еднакви единици.','Въведи шест покупки от две категории. Обобщи стойностите по категория и сравни със сбора на всички редове.','number','Категория A има 4, 6 и 10 евро; B има 3 и 7 евро.','Сбор за A=>20~Сбор за B=>10~Общ сбор=>30','Сборът на груповите суми трябва да съвпада с общата сума.']]);
addResources(9,'Създаване на съдържание с програмни средства',[
['Модули, пакети и библиотеки','Модулът предоставя готови функции; пакетът организира модули. Първо проверяваме официалната документация и нуждата от външна зависимост. Стандартни модули като math не изискват отделно инсталиране.','Използвай Python math за корен квадратен и закръгляне нагоре. Посочи коя функция използваш и провери резултата ръчно.','number','При import math намери резултата.','math.sqrt(81)=>9~math.ceil(2.2)=>3~math.floor(2.9)=>2','ceil закръгля към по-голямото цяло, floor — към по-малкото.'],
['Избор, използване и проверка на пакет','Проверяваме предназначение, документация, лиценз и съвместимост. Инсталацията в учебна среда е според указанията на учителя. След това изпълняваме малък пример с известен резултат.','Проучи библиотека за диаграми, без да я инсталираш самостоятелно. Намери официален пример и обясни входните му данни.','order','Подреди избора на библиотека.','Описвам нужната възможност~Проверявам официален пакет и документация~Сравнявам лиценз и съвместимост~Следвам разрешения начин за инсталиране~Тествам минимален пример','Името на непознат пакет не е достатъчно доказателство за надеждност.']]);
addResources(9,'Работа по проект в екип',[
['Проблем, документация и защита','Проектът започва с проблем и критерии за успех. Екипът планира, разработва, документира и тества. При защита показва резултат и обосновава избраните технологии.','Създайте модел за организиране на еко кампания: таблица с материали, покана по шаблон и визуално представяне. Използвайте само измислени лични записи.','match','Свържи въпрос и раздел от документацията.','Защо го правим?=>Проблем и цел~Кога и от кого?=>План и роли~Как работи?=>Описание на решението~Как доказваме резултата?=>Тестове и критерии','Критериите трябва да могат да бъдат проверени.']]);
addResources(10,'Обработка на информацията и комуникация',[
['Погрешна информация и дезинформация','Невярна информация може да се разпространи по погрешка или умишлено. Намерението не се доказва само от неточността. Проверяваме първоизточник, дата, контекст и независими доказателства.','Анализирай измислено твърдение „Утре всички училища затварят“. Направи план за проверка чрез официални източници, без да го препубликуваш като факт.','order','Подреди проверката.','Формулирам точно твърдението~Намирам първоизточник и дата~Проверявам независими надеждни данни~Сравнявам контекст и доказателства~Правя извод и посочвам ограниченията','Многото споделяния не са независимо доказателство.'],
['Deepfake, clickbait и влияние на AI','Генерираното съдържание може да изглежда убедително без да описва реално събитие. Clickbait използва подвеждащо привличане на внимание. Проверяваме произхода и съпоставяме фактите, вместо да разчитаме само на видими дефекти.','Създай две заглавия за една и съща измислена учебна новина: точно и подвеждащо. Обясни разликата и пренапиши подвеждащото.','match','Свържи пример и проблем.','Заглавие обещава друго от текста=>Подвеждащо заглавие~Синтезиран глас е представен като реален запис=>Потенциална дълбока фалшификация~Липсват източник и дата=>Недостатъчна проверимост~Проверка само по броя гледания=>Ненадежден критерий','Проверката на произхода е по-силна от усещането, че нещо изглежда истинско.'],
['Облачни услуги и споделяне между устройства','Облачните услуги могат да съхраняват, синхронизират и споделят файлове. Синхронизирането може да разпространи и нежелана промяна. Управляваме права, версии и резервни копия според задачата.','Планирай работа по документ от две устройства. Опиши как проверяваш последната версия и как възстановяваш по-стара при грешка.','match','Свържи нужда и функция.','Една версия на две устройства=>Синхронизация~Преглед от друг човек=>Споделяне с права~Връщане след грешна редакция=>История на версии~Защита при загуба според отделен план=>Резервно копие','Синхронизацията не е пълна замяна на резервното копиране.']]);
addResources(10,'Програмиране и изкуствен интелект',[
['Свойства и представяне на алгоритми','Алгоритъмът описва изпълними стъпки и резултат за зададен клас входове. Определеността изисква ясни инструкции, крайността — приключване. Можем да го представим словесно, с псевдокод или програма.','Опиши алгоритъм за по-голямото от две числа. Представи го с псевдокод и Python и провери случая с равни числа.','match','Свържи свойство и обяснение.','Определеност=>Стъпките са недвусмислени~Крайност=>Изпълнението приключва~Масовост=>Решава клас сходни задачи~Дискретност=>Разделен е на стъпки','Алгоритъмът трябва да е ясен и за граничните входове.'],
['Линейни и разклонени алгоритми','Линейният алгоритъм изпълнява последователни стъпки. Разклонението избира според условие. Проследяването на стойностите след всяка инструкция помага да проверим резултата.','Напиши програма за отстъпка: при сума поне 50 евро намали с 10%, иначе запази цената. Провери 49, 50 и 60.','number','За правилото от задачата въведи крайната цена.','Покупка 40 евро=>40~Покупка 50 евро=>45~Покупка 60 евро=>54','При точно 50 условието е вярно.'],
['Цикли и натрупване','Цикълът повтаря инструкции. Акумулаторът започва от начална стойност и се обновява при всяка итерация. При празен набор избягваме недопустимо деление при изчисляване на средна стойност.','Намери сума и средно на списък с числа. Определи отделно поведение за празен списък и обясни защо.','number','За данните [2, 4, 6, 8] пресметни:','Брой елементи=>4~Сума=>20~Средноаритметично=>5','Натрупаната сума се дели на броя само когато броят е положителен.'],
['Набори от данни и качество','Наборът от данни има записи, полета и описания. Проверяваме източник, лиценз, единици, липсващи и дублирани стойности. Неподходящите данни могат да доведат до грешен извод дори при правилен код.','Създай измислен набор с дата и температура. Добави една липсваща и една очевидно грешна стойност. Опиши как ще ги обработиш.','match','Свържи проблем и проверка.','Температура без единица=>Проверявам описанието~Празно поле=>Определям правило за липсващи стойности~Повторен запис=>Проверявам дублирането~Неизвестен произход=>Проверявам източника','Не замествай автоматично липсваща стойност с нула.'],
['Обработка на данни с Python','Списъци, цикли и вградени функции позволяват сумиране, търсене на крайни стойности и филтриране. Проверяваме типа и валидността на данните преди изчисление.','За [12, 18, 15, 21] намери минимум, максимум, сбор и средно. После изведи само стойностите над 15.','number','За [12, 18, 15, 21] намери:','min=>12~max=>21~sum=>66~Средно=>16.5','Сборът е 66; раздели на четирите наблюдения.'],
['Визуализиране и интерпретация','Графиката трябва да има подходящ тип, оси и единици. Промяната на скалата може да подчертае или прикрие разлики. Корелацията сама по себе си не доказва причинност.','Покажи едни и същи четири стойности на две диаграми с различна скала. Обясни как се променя впечатлението.','match','Свържи елемент и роля.','Означена ос=>Показва величина и единица~Легенда=>Обяснява серии или цветове~Скала=>Определя визуалния мащаб~Източник=>Позволява проверка на данните','Изводът се основава на стойностите и контекста, а не само на формата на линията.'],
['Машинно обучение: тренировъчни и тестови данни','При обучение моделът настройва параметри по тренировъчни данни. Тестовите данни се пазят отделно за оценка върху невиждани примери. Отличен резултат върху научените примери не гарантира добро обобщаване.','Раздели 20 измислени примера на 16 за обучение и 4 за тест. Обясни защо не оценяваш само върху същите 16.','match','Свържи роля и описание.','Тренировъчен набор=>Използва се за обучение~Тестов набор=>Проверява невиждани примери~Целева стойност=>Това което моделът трябва да предвиди~Признаци=>Входни характеристики','Тестовите примери не трябва да се използват за напасване на решението.'],
['Заявки към AI и проверка на резултатите','Полезната заявка посочва цел, контекст, ограничения и критерий за проверка. AI може да измисли факти или източници. Използваме минимални необходими данни и проверяваме резултата независимо.','Поискай план за анализ на измислени данни за рециклиране. Провери изчисленията ръчно и отбележи кои предложения са приложими.','order','Подреди работата с AI.','Определям задачата и критериите~Подготвям несекретни примерни данни~Формулирам ясна заявка~Проверявам факти и пресмятания~Редактирам и използвам проверения резултат','Отговорът е предложение, а не доказателство за собствената си вярност.']]);
addResources(10,'Решаване на проблеми и безопасност',[
['Избор на метод и технологично решение','Един проблем може да има различни решения. Сравняваме точност, време, достъпност и нужни ресурси. Избираме според критериите, а не само защото инструментът е нов или популярен.','Сравни ръчно пресмятане, електронна таблица и Python за 10 и за 10 000 записа. Обоснови различния избор.','match','Свържи задача и разумна отправна точка.','Еднократно 2 + 3=>Ръчно пресмятане~Бюджет с редовни редакции от начинаещ екип=>Електронна таблица~Повтаряща се обработка на хиляди записи=>Скрипт~Неясни изисквания=>Първо уточняване на целта','Това са отправни точки; изборът зависи и от уменията на екипа.'],
['Мрежови рискове и безопасни навици','Защитата включва актуализации, отделни пароли, многофакторно удостоверяване и ограничени права. При инцидент действаме по установения ред и пазим необходимите сведения без допълнително разпространяване на чувствителни данни.','Направи план за реакция при изгубен учебен акаунт. Посочи доверен канал за възстановяване и какви действия не трябва да се предприемат.','match','Свържи риск и мярка.','Изтекла повторно използвана парола=>Смяна и отделни пароли~Позната уязвимост=>Актуализация~Загуба на важен документ=>Проверено резервно копие~Ненужни права=>Ограничаване до необходимото','Използвай официален канал за възстановяване, а не непозната услуга.'],
['Дигитално благополучие и устойчивост','Продължителната работа без почивка може да натоварва. Планираме баланс между екран, движение и сън. Електронните устройства имат жизнен цикъл; ремонтът, повторната употреба и правилното предаване на отпадъци намаляват въздействието.','Направи седмичен план с почивки и дейности без екран. Предложи три начина за по-дълга употреба на училищна техника.','match','Свържи действие и цел.','Редовни почивки=>Баланс и намаляване на натоварването~Ремонт при възможност=>Удължаване живота на устройство~Предаване на електронен отпадък по правилния ред=>Отговорно третиране~Изключване на ненужна техника=>Намаляване на излишната консумация','Планирай конкретни навици, които можеш да спазваш.'],
['Самооценка и интегриран проект','Самооценката сравнява уменията с конкретни доказателства. Проектът съчетава анализ на данни, проверка на източници, представяне и защита. Изводите трябва да посочват и ограниченията на използваните данни.','Създай проект „Дигитални навици“ с измислени обобщени данни. Обработи ги, визуализирай, напиши изводи и предложи подобрения без реални лични сведения.','order','Подреди завършването на проекта.','Проверявам данните и източниците~Извършвам анализа~Визуализирам резултатите~Формулирам изводи и ограничения~Оценявам уменията си и представям проекта','Самооценката се подкрепя с конкретна работа, а не само с усещане.']]);
