resourceBank[4].forEach(t=>{if(t.unit==='Образователни игри и дигитален проект')t.unit=t.title==='Разработване и защита на проект'?'Дигитален проект':'Образователни игри';});
addResources(5,'Компютърна текстообработка',[
['Въвеждане на български текст и пунктуация','Избираме подходяща клавиатурна подредба за български. Поставяме интервал след обичайните пунктуационни знаци, а не пред тях. Enter започва нов абзац, а автоматичното пренасяне на ред не е нов абзац.','Напиши три изречения за любим дигитален проект. Поправи интервалите и отдели текста в два смислени абзаца.','match','Свържи задача и средство.','Въвеждане на кирилица=>Българска клавиатурна подредба~Нов абзац=>Enter~Поправка на предходен знак=>Backspace~Разделяне на две думи=>Интервал','Не добавяй ръчно нов абзац в края на всеки видим ред.']]);
addResources(5,'Компютърна презентация',[
['Създаване, редактиране и съхраняване на слайдове','Оформлението определя полетата на слайда. Вмъкваме текст и изображение, подреждаме слайдовете и запазваме работния файл. Изтриването на слайд и премахването на обект от него са различни действия.','Направи три слайда със заглавие, съдържание и покана. Размени втория и третия и сравни дали разказът остава логичен.','match','Коя операция е нужна?','Нова страница в презентацията=>Нов слайд~Друг ред на изложението=>Преместване на слайд~Поправка на надпис=>Редакция на текст~Запазване на възможността за промени=>Запис на работния файл','Преди представяне провери последователността и файла.']]);
addResources(6,'Интернет и интегриране на дейности',[
['Търсене на чужд език и електронни речници','Ключовите думи на различни езици могат да дадат различни резултати. Речникът помага за значението, но преводът трябва да се провери в контекст. Запазваме източниците и не представяме чужд текст като собствен.','Потърси информация за рециклиране на хартия с български и английски ключови думи. Сравни два източника и запиши по три полезни понятия.','match','Свържи термин и значение.','recycling=>Рециклиране~source=>Източник~copyright=>Авторско право~search=>Търсене','Провери дали значението е подходящо точно за темата.']]);
addResources(8,'Програмиране и изкуствен интелект',[
['Сензори, обучение и персонализирани препоръки','Дигиталните услуги използват данни за препоръки и анализ. Сензорите могат да генерират измервания, а поведението в платформа — други данни. Проверяваме какво се събира и управляваме настройките според нуждата.','Опиши измислена музикална платформа. Посочи какви данни биха повлияли на препоръките и кои разрешения не са необходими за слушане на песни.','match','Какъв е видът на данните?','Температура от термометър=>Сензорно измерване~Списък слушани песни=>Данни за поведение~Натиснато Харесвам=>Предпочитание~Домашен адрес без необходимост=>Ненужни лични данни','Не всяка функция изисква достъп до всички данни на устройството.']]);
addResources(10,'Програмиране и изкуствен интелект',[
['Сензорни данни и пристрастия на модел','Обучението зависи от примери и тяхната представителност. Данни само от една среда могат да доведат до по-слаб резултат в друга. Сензорните грешки и неподходящите етикети също влияят на качеството.','Измислен модел разпознава листа, но е обучен само със снимки на бял фон. Планирай тест със снимки на различни фонове и осветление.','match','Свържи проблем и подход.','Само един вид фон=>Добавям разнообразни примери~Грешно означен вид листо=>Проверявам етикетите~Сензорът отчита невъзможна стойност=>Проверявам измерването~Слаб резултат върху нови примери=>Изследвам обобщаването','Повече данни не решават автоматично проблема, ако повтарят същата грешка.']]);
